(()=>{
const $=id=>document.getElementById(id);let lastSpin=null,lastEvent=null,animation=null,hide=null,previous=null,context=null;
function sound(s,type){if(!s.settings.sound||window.BATTLE_OVERLAY)return;try{context??=new (window.AudioContext||window.webkitAudioContext)();context.resume();const oscillator=context.createOscillator(),gain=context.createGain(),t=context.currentTime;oscillator.type='sine';oscillator.frequency.setValueAtTime(type==='winner'?440:type==='timer'?200:300,t);oscillator.frequency.exponentialRampToValueAtTime(type==='winner'?880:600,t+.18);gain.gain.setValueAtTime(.04,t);gain.gain.exponentialRampToValueAtTime(.001,t+.25);oscillator.connect(gain);gain.connect(context.destination);oscillator.start(t);oscillator.stop(t+.28)}catch{}}
function render(s){const totals=Battle.scores(s);if(previous)for(const p of Battle.active(s))if(totals[p.id]!==previous[p.id])$('score-'+p.id)?.animate([{transform:'scale(1)'},{transform:'scale(1.18)',filter:'brightness(1.5)'},{transform:'scale(1)'}],{duration:450,easing:'ease-out'});previous=totals;
if(s.spin&&s.spin.id!==lastSpin){lastSpin=s.spin.id;runSpin(s.spin,s)}if(s.event&&s.event.id!==lastEvent){lastEvent=s.event.id;winner(s.event,s)}}
async function runSpin(spin,s){const elapsed=Date.now()-spin.startedAt;if(elapsed>7400)return;clearTimeout(hide);animation?.cancel();const stage=$('roulette'),track=$('rail');stage.hidden=false;stage.classList.remove('revealed');$('fx-mode').textContent='MATCH ROULETTE';$('fx-title').textContent='LET FATE DECIDE.';$('fx-name').textContent=spin.game.name;$('fx-rule').textContent=spin.game.win;$('fx-points').textContent='SIEG +'+Battle.nextPoints(s);$('fx-phase').textContent='FILTER LOCKED / ROULETTE ARMED';$('fx-count').textContent=Battle.active(s).length+' SPIELER · '+Battle.eligible(s).length+' WEITERE GAMES';$('roulette-sparks').replaceChildren();track.replaceChildren(...spin.sequence.map((g,i)=>{const card=document.createElement('div');card.className='spin-card tone-'+(i%4)+(i===34?' chosen':'');const icon=document.createElement('b');icon.textContent=g.icon;const name=document.createElement('strong');name.textContent=g.name;const mode=document.createElement('small');mode.textContent=g.mode;card.append(icon,name,mode);return card}));sound(s,'spin');
await new Promise(r=>setTimeout(r,Math.max(0,spin.startedAt-Date.now())));if(lastSpin!==spin.id)return;const center=$('rail-window').clientWidth/2;animation=track.animate([{transform:`translateX(${center-90}px)`},{transform:`translateX(${center-6618}px)`}],{duration:spin.duration,easing:'cubic-bezier(.08,.64,.08,1)',fill:'forwards'});animation.currentTime=Math.max(0,Date.now()-spin.startedAt);const progress=$('fx-progress').animate([{transform:'scaleX(0)'},{transform:'scaleX(1)'}],{duration:spin.duration,fill:'forwards'});progress.currentTime=Math.max(0,Date.now()-spin.startedAt);$('fx-phase').textContent='SHUFFLING / LET FATE DECIDE';await new Promise(r=>setTimeout(r,Math.max(0,spin.duration-(Date.now()-spin.startedAt))));if(lastSpin!==spin.id)return;stage.classList.add('revealed');$('fx-title').textContent='DAS IST EUER MATCH.';$('fx-phase').textContent='LOCKED / LET’S PLAY';sparks($('roulette-sparks'));sound(s,'winner');hide=setTimeout(()=>stage.hidden=true,Math.max(100,7400-(Date.now()-spin.startedAt)));}
function winner(e,s){const elapsed=Date.now()-e.at;if(elapsed>3000)return;const stage=$('victory');stage.hidden=false;stage.className='victory';const p=Battle.player(s,e.winner);stage.querySelector('.victory-card').style.setProperty('--winner',p?.color||'#c1a0ff');sparks($('victory-sparks'));$('victory-tag').textContent=e.type==='timer'?'TIME IS UP':e.final?'FINAL CHALLENGE':'CHALLENGE COMPLETE';$('victory-name').textContent=e.type==='timer'?'ZEIT ABGELAUFEN':e.winner===null?'UNENTSCHIEDEN':(p?.name||'Spieler')+' GEWINNT';$('victory-detail').textContent=e.type==='timer'?'Zeit vorbei. Vergleicht eure Ergebnisse.':e.winner===null?'Je 0 Punkte · Gleichstand gespeichert':'+'+e.points+' '+(e.points===1?'Punkt':'Punkte')+' · '+(e.gameName||'');if(e.type!=='timer'&&e.allocations)$('victory-detail').textContent=Object.entries(e.allocations).filter(([id,n])=>n>0).map(([id,n])=>(Battle.player(s,id)?.name||'Spieler')+' +'+n).join(' · ')||'Keine Punkte vergeben';sound(s,e.type==='timer'?'timer':'winner');setTimeout(()=>stage.hidden=true,Math.max(100,3000-elapsed))}
function sparks(root){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;root.replaceChildren(...Array.from({length:30},(_,i)=>{const el=document.createElement('i'),a=i/30*Math.PI*2,d=120+Math.random()*260;el.style.setProperty('--x',Math.cos(a)*d+'px');el.style.setProperty('--y',Math.sin(a)*d+'px');el.style.setProperty('--delay',Math.random()*.1+'s');return el}));setTimeout(()=>root.replaceChildren(),1500)}
window.BattleFX={render,sound};
})();
